from typing import List

def word_break(s: str, word_dict: List[str]) -> List[str]:
    def backtrack(start):
        if start == len(s):
            return [[]]
        result = []
        for end in range(start + 1, len(s) + 1):
            prefix = s[start:end]
            if prefix in word_dict:
                for suffix in backtrack(end):
                    result.append([prefix] + suffix)
        return result

    sentences = backtrack(0)
    return [' '.join(sentence) for sentence in sentences]

# Example usage:
# print(word_break("catsanddog", ["cat","cats","and","sand","dog"]))  # Output: ['cat sand dog', 'cats and dog']
# print(word_break("pineapplepenapple", ["apple","pen","applepen","pine","pineapple"]))  # Output: ['pine apple pen apple', 'pineapple pen apple']
# print(word_break("catsandog", ["cats","dog","sand","and","cat"]))  # Output: []
